"use client";
import { useState } from "react";
import { useRouter } from "next/navigation";
import type { SecureVendorOfferProjection, VendorProposalOption } from "@/lib/dispatch/vendor-offer-portal-types";
import { addVendorDriverForOffer, addVendorVehicleForOffer, proposeVendorResources, respondToVendorOffer } from "./actions";

const field = "mt-1 w-full rounded border bg-white p-3";
const reviewLabel = (item: VendorProposalOption) => `${item.label}${item.reviewRequired ? " — New — RentKA review required" : ""}`;

export default function VendorOfferResponse({ token, offer }: { token: string; offer: SecureVendorOfferProjection }) {
  const router = useRouter(), [mode, setMode] = useState<"" | "declined" | "countered">(""), [busy, setBusy] = useState(false),
    [message, setMessage] = useState(""), [error, setError] = useState(""), [addingDriver, setAddingDriver] = useState(false), [addingVehicle, setAddingVehicle] = useState(false),
    [drivers, setDrivers] = useState(offer.eligibleDrivers), [vehicles, setVehicles] = useState(offer.eligibleVehicles),
    [driverId, setDriverId] = useState(offer.currentProposal?.driverId ?? ""), [vehicleId, setVehicleId] = useState(offer.currentProposal?.vehicleId ?? "");
  const run = async (work: () => Promise<{ ok: boolean; message: string }>) => { setBusy(true); setError(""); const result = await work(); setBusy(false); if (result.ok) setMessage(result.message); else setError(result.message); return result; };
  const respond = async (form: FormData) => { const result = await run(() => respondToVendorOffer(token, form)); if (result.ok) { setMode(""); router.refresh(); } };
  const addDriver = async (form: FormData) => { setBusy(true); const result = await addVendorDriverForOffer(token, form); setBusy(false); setError(""); if (!result.ok || !result.option) { setError(result.message); return; } setMessage(result.message); setDrivers((items) => [...items.filter((item) => item.id !== result.option!.id), result.option!]); setDriverId(result.option.id); setAddingDriver(false); router.refresh(); };
  const addVehicle = async (form: FormData) => { setBusy(true); const result = await addVendorVehicleForOffer(token, form); setBusy(false); setError(""); if (!result.ok || !result.option) { setError(result.message); return; } setMessage(result.message); setVehicles((items) => [...items.filter((item) => item.id !== result.option!.id), result.option!]); setVehicleId(result.option.id); setAddingVehicle(false); router.refresh(); };
  const propose = async () => { const form = new FormData(); form.set("driverId", driverId); form.set("vehicleId", vehicleId); const result = await run(() => proposeVendorResources(token, form)); if (result.ok) router.refresh(); };
  if (offer.closed) return <p className="rounded-xl bg-slate-100 p-4 font-bold">This vendor offer is closed or expired. Contact RentKA if you need help.</p>;
  const accepted = offer.responseStatus === "accepted", selectedDriver = drivers.find((item) => item.id === driverId), selectedVehicle = vehicles.find((item) => item.id === vehicleId),
    eligiblePair = offer.eligiblePairs.some((pair) => pair.driverId === driverId && pair.vehicleId === vehicleId), canPropose = Boolean(driverId && vehicleId && (eligiblePair || selectedDriver?.reviewRequired || selectedVehicle?.reviewRequired));
  return <div className="space-y-3">
    {message && <p className="rounded-xl bg-green-50 p-4 font-bold text-green-800">{message}</p>}
    {!offer.latestResponse && <><form action={respond}><input type="hidden" name="kind" value="accepted"/><button disabled={busy} className="w-full rounded-xl bg-green-700 px-5 py-4 text-xl font-black text-white">ACCEPT</button></form><button disabled={busy} onClick={() => setMode("declined")} className="w-full rounded-xl border-2 border-red-700 px-5 py-4 text-xl font-black text-red-700">DECLINE</button><button disabled={busy} onClick={() => setMode("countered")} className="w-full rounded-xl border-2 border-amber-700 px-5 py-4 text-xl font-black text-amber-800">COUNTER OFFER</button></>}
    {mode === "declined" && <form action={respond} className="rounded-xl border p-4"><input type="hidden" name="kind" value="declined"/><label className="font-bold">Reason<select required name="declineReason" className={field}><option value="">Select</option><option value="busy">Already booked / Busy</option><option value="vehicle_unavailable">No suitable vehicle available</option><option value="driver_unavailable">No suitable driver available</option><option value="route_not_suitable">Route not suitable</option><option value="price_too_low">Price too low</option><option value="other">Other</option></select></label><textarea name="note" maxLength={240} placeholder="Optional note; required for Other" className={field}/><button disabled={busy} className="mt-3 w-full rounded bg-red-700 p-3 font-black text-white">Confirm Decline</button></form>}
    {mode === "countered" && <form action={respond} className="rounded-xl border p-4"><input type="hidden" name="kind" value="countered"/><label className="font-bold">Requested vendor payout (Rs)<input required name="requestedPayout" inputMode="decimal" className={field}/></label><textarea name="note" maxLength={240} placeholder="Optional note" className={field}/><button disabled={busy} className="mt-3 w-full rounded bg-amber-700 p-3 font-black text-white">Submit Counter</button></form>}
    {accepted && <section className="rounded-xl border-2 border-blue-200 bg-blue-50 p-4"><h2 className="font-black">Propose fulfillment resources</h2><p className="mb-4 text-xs">Choose existing resources or add new ones here. RentKA must review and make the final assignment.</p>
      <label className="block font-bold">Driver<select required value={driverId} onChange={(event) => setDriverId(event.target.value)} className={field}><option value="">Select existing Driver</option>{drivers.map((item) => <option key={item.id} value={item.id}>{reviewLabel(item)}</option>)}</select></label>
      <button type="button" onClick={() => setAddingDriver((value) => !value)} className="mt-2 rounded border border-blue-700 bg-white px-3 py-2 text-sm font-bold text-blue-800">+ Add new driver</button>
      {addingDriver && <form action={addDriver} className="mt-3 rounded-lg border bg-white p-3"><h3 className="font-black">New Driver</h3><label className="mt-2 block text-sm font-bold">Name *<input required name="driverName" maxLength={160} className={field}/></label><label className="mt-2 block text-sm font-bold">Mobile / WhatsApp *<input required name="driverPhone" inputMode="tel" maxLength={40} className={field}/></label><p className="mt-3 text-sm font-bold">Driver verification (optional for now)</p><div className="grid gap-2 sm:grid-cols-2"><label className="text-sm">Document type<select name="driverDocumentKind" className={field}><option value="cnic_front">CNIC</option><option value="licence_front">Driving licence</option></select></label><label className="text-sm">Upload CNIC or licence<input name="driverDocument" type="file" accept="image/jpeg,image/png,application/pdf" className={field}/></label></div><button disabled={busy} className="mt-3 w-full rounded bg-blue-800 p-3 font-black text-white">Save &amp; Use for This Booking</button></form>}
      <label className="mt-4 block font-bold">Vehicle<select required value={vehicleId} onChange={(event) => setVehicleId(event.target.value)} className={field}><option value="">Select existing Vehicle</option>{vehicles.map((item) => <option key={item.id} value={item.id}>{reviewLabel(item)}</option>)}</select></label>
      <button type="button" onClick={() => setAddingVehicle((value) => !value)} className="mt-2 rounded border border-blue-700 bg-white px-3 py-2 text-sm font-bold text-blue-800">+ Add new vehicle</button>
      {addingVehicle && <form action={addVehicle} className="mt-3 rounded-lg border bg-white p-3"><h3 className="font-black">New Vehicle</h3><div className="grid gap-2 sm:grid-cols-2"><label className="text-sm font-bold">Make *<input required name="vehicleMake" maxLength={80} className={field}/></label><label className="text-sm font-bold">Model *<input required name="vehicleModel" maxLength={100} className={field}/></label><label className="text-sm font-bold">Registration number *<input required name="registrationNumber" maxLength={40} className={field}/></label><label className="text-sm font-bold">Year (optional)<input name="modelYear" inputMode="numeric" className={field}/></label><label className="text-sm">Registration document (optional)<input name="registrationDocument" type="file" accept="image/jpeg,image/png,application/pdf" className={field}/></label><label className="text-sm">Vehicle photo (optional)<input name="vehiclePhoto" type="file" accept="image/jpeg,image/png,application/pdf" className={field}/></label></div><button disabled={busy} className="mt-3 w-full rounded bg-blue-800 p-3 font-black text-white">Save &amp; Use for This Booking</button></form>}
      {(selectedDriver?.reviewRequired || selectedVehicle?.reviewRequired) && <p className="mt-3 rounded bg-amber-50 p-3 text-sm font-bold text-amber-900">New — RentKA review required before final assignment.</p>}
      <button type="button" onClick={propose} disabled={busy || !canPropose} className="mt-4 w-full rounded bg-blue-800 p-3 font-black text-white disabled:opacity-40">{offer.currentProposal ? "Update Proposal" : "Submit Proposal"}</button>{!canPropose && <p className="mt-2 text-sm font-bold text-amber-900">Select a compatible Driver and Vehicle. New resources can be submitted for RentKA review.</p>}
    </section>}
    {error && <p role="alert" className="rounded-xl bg-red-50 p-3 font-bold text-red-800">{error}</p>}
    <p className="text-center text-xs text-slate-500">Acceptance and proposals do not assign the booking. RentKA retains final assignment authority.</p>
  </div>;
}
